package org.cao.backend.policy;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Random;
import org.junit.jupiter.api.Test;

class InventoryPartitionTest {
    // Digests below were generated by JSON.stringify/createHash in .github/workflows/shared/control.mjs at the source SHA.
    private static final String FIVE_VERSION =
            "sha256:b351cd4984a7e60c89d3f92639a15c6a7b1839b9f1ab40f8a98e0a54f587d416";
    private static final String EMPTY_VERSION =
            "sha256:e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";

    private static RepositoryMetadata repo(long id, String name, boolean archived, boolean disabled, boolean isPrivate,
            String pushedAt, String branch) {
        return new RepositoryMetadata(id, "acme/" + name, archived, disabled, isPrivate, pushedAt, branch);
    }

    static List<RepositoryMetadata> fixture() {
        return List.of(
                repo(30, "gamma", false, false, true, "2026-01-03T00:00:00Z", "main"),
                repo(10, "alpha", false, false, false, null, "ma\"in\\x\u2028é\u0001"),
                repo(20, "beta", true, false, true, "2026-01-02T00:00:00Z", "trunk"),
                repo(41, "delta", false, true, true, "2026-01-04T00:00:00Z", "main"),
                repo(52, "epsilon", false, false, true, "2026-01-05T00:00:00Z", "main"),
                repo(20, "beta", true, false, true, "2026-01-02T00:00:00Z", "trunk"));
    }

    private static ControlPolicy.Inventory limits(int cellCount, int cellIndex, int batchSize, int batchIndex) {
        return new ControlPolicy.Inventory(1000, cellCount, cellIndex, batchSize, batchIndex);
    }

    @Test
    void canonicalJsonMatchesJavaScriptStringify() {
        assertEquals("{\"id\":10,\"full_name\":\"acme/alpha\",\"archived\":false,\"disabled\":false,\"private\":false,"
                + "\"pushed_at\":null,\"default_branch\":\"ma\\\"in\\\\x\u2028é\\u0001\"}",
                fixture().get(1).canonicalJson());
    }

    @Test
    void versionMatchesJavaScriptDigestIndependentOfDiscoveryOrder() {
        List<RepositoryMetadata> shuffled = new ArrayList<>(fixture());
        Collections.shuffle(shuffled, new Random(7));
        for (List<RepositoryMetadata> input : List.of(fixture(), shuffled)) {
            InventoryPartition p = InventoryPartition.of(input, ControlPolicy.Inventory.DEFAULTS);
            assertEquals(FIVE_VERSION, p.version());
            assertEquals(5, p.inventoryRepositoryCount());
            assertEquals(List.of(10L, 20L, 30L, 41L, 52L), p.candidates().stream().map(RepositoryMetadata::id).toList());
            assertEquals(FIVE_VERSION + ":cell-0-of-1:batch-0-of-1", p.batchId());
        }
    }

    @Test
    void cellsAndBatchesMatchJavaScriptSelection() {
        InventoryPartition second = InventoryPartition.of(fixture(), limits(2, 0, 1, 1));
        assertEquals(4, second.cellRepositoryCount());
        assertEquals(4, second.batchCount());
        assertEquals(List.of(20L), second.candidates().stream().map(RepositoryMetadata::id).toList());
        assertEquals(FIVE_VERSION + ":cell-0-of-2:batch-1-of-4", second.batchId());

        InventoryPartition odd = InventoryPartition.of(fixture(), limits(2, 1, 10, 0));
        assertEquals(List.of(41L), odd.candidates().stream().map(RepositoryMetadata::id).toList());
        assertEquals(FIVE_VERSION + ":cell-1-of-2:batch-0-of-1", odd.batchId());
    }

    @Test
    void cellsPartitionTheInventoryWithoutOverlap() {
        List<Long> all = new ArrayList<>();
        for (int cell = 0; cell < 3; cell++) {
            for (RepositoryMetadata r : InventoryPartition.of(fixture(), limits(3, cell, 100, 0)).candidates()) {
                all.add(r.id());
            }
        }
        Collections.sort(all);
        assertEquals(List.of(10L, 20L, 30L, 41L, 52L), all);
    }

    @Test
    void emptyInventoryHasEmptyDigestAndNoBatches() {
        InventoryPartition p = InventoryPartition.of(List.of(), ControlPolicy.Inventory.DEFAULTS);
        assertEquals(EMPTY_VERSION, p.version());
        assertEquals(0, p.batchCount());
        assertTrue(p.candidates().isEmpty());
        assertEquals(EMPTY_VERSION + ":cell-0-of-1:batch-0-of-0", p.batchId());
    }

    @Test
    void batchBeyondNonEmptyCellScanBoundAndBadIdentityAreFatal() {
        assertThrows(PolicyException.class, () -> InventoryPartition.of(fixture(), limits(1, 0, 10, 1)));
        assertThrows(PolicyException.class,
                () -> InventoryPartition.of(fixture(), new ControlPolicy.Inventory(4, 1, 0, 10, 0)));
        assertThrows(PolicyException.class, () -> repo(0, "x", false, false, false, null, null));
        assertThrows(PolicyException.class,
                () -> new RepositoryMetadata(1, "not a repo", false, false, false, null, null));
    }

    @Test
    void parserAcceptsInventoryAndRejectsInvalidValues() {
        ControlPolicy p = PolicyParser.parse(bytes("{\"version\":1,\"control-plane\":{\"inventory\":"
                + "{\"max-scan-repositories\":50,\"cell-count\":4,\"cell-index\":3,\"batch-size\":7,\"batch-index\":2}}}"));
        assertEquals(new ControlPolicy.Inventory(50, 4, 3, 7, 2), p.inventory());
        assertEquals(ControlPolicy.Inventory.DEFAULTS,
                PolicyParser.parse(bytes("{\"version\":1,\"control-plane\":{}}")).inventory());
        for (String bad : List.of("{\"cell-count\":2,\"cell-index\":2}", "{\"cell-index\":1}", "{\"cell-count\":1001}",
                "{\"max-scan-repositories\":0}", "{\"max-scan-repositories\":100001}", "{\"batch-size\":0}",
                "{\"batch-index\":-1}", "{\"batch-index\":\"1\"}", "{\"extra\":1}", "[]")) {
            assertThrows(PolicyException.class, () -> PolicyParser.parse(
                    bytes("{\"version\":1,\"control-plane\":{\"inventory\":" + bad + "}}")), bad);
        }
    }

    private static byte[] bytes(String json) {
        return json.getBytes(StandardCharsets.UTF_8);
    }
}
